Section WithRIP.
Hypothesis RIP : rip_stmt.

Definition istrchr_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (r : Z) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 r) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - ISTRCHR_DEPTH, bv_unsigned sp)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp).

Theorem istrchr_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (s c : Z) (w8 : list byte) (lo : Z),
  a0 = Z_to_bv 64 s -> (bv_unsigned a1) mod 256 = c -> 0 < c ->
  In w8 LIT8 -> bytes_at asegs m s w8 -> s mod 8 = 0 -> 0 < s -> s + 8 <= lo ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - ISTRCHR_DEPTH -> kHighShadowEnd + 8 <= lo -> bv_unsigned sp + 16 <= 2^47 ->
  (forall n, 1 <= n <= w8_strlen w8 + 1 -> chk_ok m s n) -> m2s_cells m -> icells_sn m -> icells_strchr m -> mem_inv asegs m ->
  evt asegs (istrchr_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc (strchr_res s c w8) lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
